-- =============================================================================
-- NINHO — CATÁLOGO SEMÂNTICO: 01_meta_glossario.sql (PROJETO: GLD)
-- Carga idempotente via MERGE INTO
-- =============================================================================

MERGE INTO DW_GLD.META_GLOSSARIO dst
USING (SELECT 'GLD' AS PROJETO, 'ORGAO_PUBLICO' AS DOMINIO, 'DIMENSAO_ORGAO_PUBLICO' AS IDENTIFICADOR, 'Entidade oficial de dimensao para ORGAO_PUBLICO no projeto GLD.' AS DESCRICAO, 'DIM_ORGAO_PUBLICO, VW_GLD_DIM_ORGAO_PUBLICO_ATUAL' AS SINONIMOS, 'Ver catálogo de domínio' AS EXEMPLOS_VALORES, 'Consultar preferencialmente via view semântica VW_GLD_DIM_ORGAO_PUBLICO_ATUAL.' AS REGRA_USO, 'DIMENSAO' AS CLASSIFICACAO FROM DUAL) src
ON (dst.PROJETO = src.PROJETO AND dst.DOMINIO = src.DOMINIO AND dst.IDENTIFICADOR = src.IDENTIFICADOR)
WHEN MATCHED THEN UPDATE SET dst.DESCRICAO = src.DESCRICAO, dst.SINONIMOS = src.SINONIMOS, dst.REGRA_USO = src.REGRA_USO, dst.CLASSIFICACAO = src.CLASSIFICACAO
WHEN NOT MATCHED THEN INSERT (PROJETO, DOMINIO, IDENTIFICADOR, DESCRICAO, SINONIMOS, EXEMPLOS_VALORES, REGRA_USO, CLASSIFICACAO)
VALUES (src.PROJETO, src.DOMINIO, src.IDENTIFICADOR, src.DESCRICAO, src.SINONIMOS, src.EXEMPLOS_VALORES, src.REGRA_USO, src.CLASSIFICACAO);

MERGE INTO DW_GLD.META_GLOSSARIO dst
